entries[181315] = { ["name"] = "Blutschmauserspinnling", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick diesen Begleiter beschwören oder wieder freigeben.\n80 ( 80)\nIhr benötigt mindestens einen wohlwollenden Ruf bei den Flickmeistern.\nVerdient den Erfolg \"Klitzekleine Kämpfer\", um dieses Haustier zu kaufen." }
entries[181316] = { ["name"] = "Silberspitzenfledderschwinge", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nIhr benötigt einen ehrfürchtigen Ruf bei den Flickmeistern.\nErfordert einen ehrfürchtigen Ruf beim Gluthof.\nVerdient den Erfolg \"Verflucht durstig\", um dieses Reittier zu kaufen.\n\n\"Diese von Prinz Renathal von Revendreth gezüchteten seltenen Fledderschwingen sind äußerst loyal und lassen nur jene an sich heran, die vom Prinzen selbst als würdig erachtet werden.\"\nPaktfeature:\nDer Gluthof\nPakt:\nVenthyr\n\nPaktfeature:\nKonservatorium der Königin\nPakt:\nNachtfae\n\nPaktfeature:\nPfad des Aufstiegs\nPakt:\nKyrianer\n\nPaktfeature:\nMonstrositätenfabrik\nPakt:\nNekrolords" }
entries[181317] = { ["name"] = "Unbeirrbarer Abendläufer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nIhr benötigt einen ehrfürchtigen Ruf bei den Flickmeistern.\n\n\"Der Pfad des Aufstiegs ist eine anspruchsvolle Prüfung und wer alle Eigenschaften unter Beweis stellt, die die Kyrianer schätzen, soll seinen rechtmäßigen Lohn erhalten.\"\nPaktfeature:\nDer Gluthof\nPakt:\nVenthyr\n\nPaktfeature:\nKonservatorium der Königin\nPakt:\nNachtfae\n\nPaktfeature:\nPfad des Aufstiegs\nPakt:\nKyrianer\n\nPaktfeature:\nMonstrositätenfabrik\nPakt:\nNekrolords" }
