entries[181357] = { ["name"] = "Tafel der Verzweiflung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+14 Intelligenz\nBenutzen: Lässt das Ziel im Verlauf von 25 Sek. bis zu ( 68 * 20.78125) Schattenschaden erleiden. Der Schaden von 'Wachsende Verzweiflung' erhöht sich im Lauf der Dauer. (2 Min Abklingzeit)\n\"In den falschen Händen kann so manches Werkzeug zur Waffe werden.\"\nVerkaufspreis:" }
