entries[181359] = { ["name"] = "Überquellender Glutspiegel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+14 [Beweglichkeit oder Stärke oder Intelligenz]\nBenutzen: Gewährt einen Absorptionsschild, der 20% des Euch in den nächsten 12 Sek. zugefügten Schadens verhindert, bis zu maximal 3635 Schaden. 33% der verbleibenden Absorption explodieren und verursachen Schaden, der auf alle Gegner innerhalb von 8 Metern aufgeteilt wird. (2 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[181360] = { ["name"] = "Aufgeladener Glutsplitter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+ 20 Vielseitigkeit\nBenutzen: Kann auf ein verbündetes Ziel kanalisiert werden, um im Verlauf von 6 Sek. bis zu [ 4106 * (1 + Vielseitigkeit)] Gesundheit wiederherzustellen, die auf alle Verbündeten aufgeteilt wird, die vom 40 Meter großen Strahl erfasst werden. Kann auf ein gegnerisches Ziel kanalisiert werden, um im Verlauf von 6 Sek. bis zu [ 3046 * (1 + Vielseitigkeit)] Heiligschaden zu verursachen, der auf alle Gegner aufgeteilt wird, die vom 40 Meter großen Strahl erfasst werden. Schaden und Heilung werden pro getroffenem Ziel leicht erhöht. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[181361] = { ["name"] = "Hoftratsch", ["text"] = "Gluthof\nWird beim Aufheben gebunden\nBenutzen: Setzt ein Gerücht in die Welt, das sich unter Humanoiden in der Nähe verbreitet.\n\n+Aufregend pro Person, die das Gerücht erreicht.\n\"Prinz Renathal möchte solch müßiges Gerede gewiss unter Kontrolle halten. ( +Entspannt )\"" }
