entries[181436] = { ["name"] = "Frisierspiegel", ["text"] = "Gluthof\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Fügt Eurem Gluthof dauerhaft einen Frisierspiegel hinzu, mit dem Ihr das Abbild Eurer Gäste auf magische Weise einfangen könnt.\nVerkaufspreis:" }
entries[181437] = { ["name"] = "Trainingsattrappen", ["text"] = "Gluthof\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Fügt Eurem Gluthof dauerhaft Trainingsattrappen hinzu, damit Ihr Eure Stärke zeigen und so die Aufregung erhöhen könnt.\n\"Ein paar Seuchenflecken sind an ihnen zu erkennen, aber im Großen und Ganzen sind sie funktionstüchtig.\"\nVerkaufspreis:" }
entries[181438] = { ["name"] = "Die Wilde Trommel", ["text"] = "Gluthof\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Fügt Eurem Gluthof dauerhaft die Wilde Trommel hinzu, mit der Ihr Eure Gäste inspirieren und sie für gewisse Zeit deutlich effektiver im Kampf machen könnt.\n\"Diese Trommel, deren Klang an das Grollen einer Bestie ihrer Heimatwelt erinnert, beflügelt selbst die größten Krieger.\"\nVerkaufspreis:" }
entries[181439] = { ["name"] = "Beschützende Kohlenpfannen", ["text"] = "Gluthof\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Fügt Eurem Gluthof dauerhaft beschützende Kohlenpfannen hinzu, mit denen Ihr Euren Gästen magischen Schutz gewähren könnt.\nVerkaufspreis:" }
entries[181440] = { ["name"] = "Schlüpfriger Schlamm", ["text"] = "Gluthof\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Fügt Eurem Gluthof dauerhaft Glitschi hinzu, einen äußerst glitschigen Gräber, den Ihr dann versuchen könnt zu fangen.\nVerkaufspreis:" }
entries[181441] = { ["name"] = "Altar der Errungenschaften", ["text"] = "Gluthof\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Fügt Eurem Gluthof dauerhaft einen Altar der Errungenschaften hinzu, mit dem Ihr Eure Erfolge in den Schattenlanden präsentieren und verschiedene Boni erhalten könnt!\nErfordert einen wohlwollenden Ruf beim Gluthof.\nVerkaufspreis:" }
entries[181442] = { ["name"] = "Visionen von Graf Denathrius", ["text"] = "Gluthof\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Fügt Eurem Gluthof dauerhaft eine Vision von Graf Denathrius hinzu, sodass Theotar die Vision beschwören kann, um Eure Gäste zu erschrecken.\nVerkaufspreis:" }
entries[181443] = { ["name"] = "Der festliche Hut des Festherolds", ["text"] = "Gluthof\nWird an Kriegsmeute gebunden\nEinzigartig\nBenutzen: Fügt Eurem Gluthof dauerhaft Temels Festheroldhut hinzu, der Euren Rufzuwachs beim Gluthof um 30% erhöht.\nErfordert einen ehrfürchtigen Ruf beim Gluthof.\n\"Selbst erfahrene Festherolde wie Temel müssen sich das Recht verdienen, diesen ultimativen festlichen Hut zu tragen!\"\nVerkaufspreis:" }
