entries[181483] = { ["name"] = "Seidenschreiterfadenspule", ["text"] = "Wird beim Aufheben gebunden\n\"Das spinnfädenartige Aussehen von Seidenschreiterfaden täuscht leicht über seine beeindruckende Dehnbarkeit hinweg. Eignet sich hervorragend als Bogensehne... für kriegerische oder heitere Zwecke.\"\nVerkaufspreis:" }
entries[181484] = { ["name"] = "Sangholzsprössling", ["text"] = "Wird beim Aufheben gebunden\n\"Älteren Bäumen wird Holz entlockt, das dann mit Setzlingen verbunden wird, um ihre Lebenskraft zu stärken und reiche Animaernten zu gewährleisten.\"\nVerkaufspreis:" }
entries[181485] = { ["name"] = "Juwelenbesetztes Bernsteinblatt", ["text"] = "Wird beim Aufheben gebunden\n\"Die Nachtfae verzichten bei der Herstellung nützlicher Werkzeuge und dekorativer Gegenstände auf Metall und verwenden stattdessen Bern.\"\nVerkaufspreis:" }
entries[181486] = { ["name"] = "Blattschuppenmantel", ["text"] = "Wird beim Aufheben gebunden\n\"Die Nachtfae verwenden statt des Fells der Runenhirsche im Ardenwald die Blätter, die auf ihnen wachsen, um dem Tier nicht zu schaden.\"\nVerkaufspreis:" }
entries[181487] = { ["name"] = "Schnur mit Leuchtbeerenperlen", ["text"] = "Wird beim Aufheben gebunden\n\"Leuchtbeeren können jahrzehntelang schimmern, wenn sie richtig entfleischt und getrocknet werden.\"\nVerkaufspreis:" }
entries[181488] = { ["name"] = "Schattenpirscherklaue", ["text"] = "Wird beim Aufheben gebunden\n\"Wenn eine Schattenpirscherpopulation zu schnell wächst, wird eine Jagd ausgerufen, um sie wieder einzudämmen.\"\nVerkaufspreis:" }
entries[181489] = { ["name"] = "Sternseesonette", ["text"] = "Wird beim Aufheben gebunden\n\"Die ausgelassenen Aufführungen des Sternseeamphitheaters sind eine erholsame Abwechslung von der ständigen Fürsorge, die die Pflege der Wildsamen erfordert.\"\nVerkaufspreis:" }
entries[181490] = { ["name"] = "Wilde Götterrune", ["text"] = "Wird beim Aufheben gebunden\n\"Geistpfleger, die über die Wiedergeburt der wilden Götter wachen, verbringen ruhige Stunden oft damit, sich Abbilder ihrer Götter als Andenken zu schnitzen.\"\nVerkaufspreis:" }
entries[181491] = { ["name"] = "Gormgrislampe", ["text"] = "Wird beim Aufheben gebunden\n\"Die natürliche Leuchtkraft von Gormgris dient als exzellente Lichtquelle für Besucher, die das ewige Zwielicht des Ardenwalds nicht gewöhnt sind.\"\nVerkaufspreis:" }
entries[181492] = { ["name"] = "Versteinerte Faeblume", ["text"] = "Wird beim Aufheben gebunden\n\"Freunde und Liebende machen sich versteinerte Blumen zum Geschenk, weil diese in ihrem niemals welkenden Zustand eine ewig währende Beziehung symbolisieren.\"\nVerkaufspreis:" }
