entries[181713] = { ["name"] = "Versengter Brief", ["text"] = "\"Es sind nur noch wenige Wörter leserlich, aber der Brief wurde bis zum Ende umklammert, um eine flüchtige Vergangenheit festzuhalten.\"\nVerkaufspreis:" }
entries[181714] = { ["name"] = "Juwelenbesetzter Handfächer", ["text"] = "Wird beim Aufheben gebunden\n\"Es ist nicht ganz leicht, alle zu bedauern, die in den Glutdistrikt verbannt wurden, denn einige von ihnen sind abschreckend dekadent.\"\nVerkaufspreis:" }
entries[181715] = { ["name"] = "Temels Abschlusszertifikat", ["text"] = "Wird beim Aufheben gebunden\n\"Dieses Zertifikat belegt, dass der Besitzer den Festherold im Zuge der Prüfungssoiree zufriedengestellt hat und somit über ausreichende Fertigkeiten verfügt, einen Gluthof abzuhalten.\"\nVerkaufspreis:" }
entries[181716] = { ["name"] = "Rekrutierungsplakate", ["text"] = "Questgegenstand\nEinzigartig\n\"Ein Flugblatt, das die Vorteile des Diensts in Nadjias Sicherheitstrupp anpreist.\"\n<Zum Lesen rechtsklicken>" }
