entries[181722] = { ["name"] = "Antike Grünspanmünze", ["text"] = "Wird beim Aufheben gebunden\n\"In diese Münze als früheres Symbol für den Erfolg in der Arena von Maldraxxus wurde das Gesicht des Primus geätzt.\"\nVerkaufspreis:" }
entries[181723] = { ["name"] = "Sorgfältig konservierter Kopf", ["text"] = "Wird beim Aufheben gebunden\n\"Die Bewahrung des Wissens scheint in Maldraxxus eine gänzlich andere Bedeutung zu haben.\"\nVerkaufspreis:" }
entries[181724] = { ["name"] = "Taktik, Band 83: Ausnutzung des Wetters", ["text"] = "Wird beim Aufheben gebunden\n\"Die materielle Beschaffenheit der Waffen Eures Feindes zu erkennen, und damit auch deren Ähnlichkeit mit einem Blitzableiter, kann Euch einen entscheidenden Hinweis zum effektivsten Einsatz wetterverändernder Magie geben.\"\nVerkaufspreis:" }
entries[181725] = { ["name"] = "Wertvoller Orden des Wächters", ["text"] = "Wird beim Aufheben gebunden\n\"Die Verteidiger von Maldraxxus erhalten einen Orden zu Ehren ihrer Verdienste um den Schutz der Schattenlande.\"\nVerkaufspreis:" }
entries[181726] = { ["name"] = "Kriegsführung, Band 27: Hinter feindlichen Linien", ["text"] = "Wird beim Aufheben gebunden\n\"Als Gefangener zu reisen, ist oft deutlich schneller als der Versuch, hinter feindlichen Linien unentdeckt zu bleiben.\"\nVerkaufspreis:" }
entries[181727] = { ["name"] = "Leere verstärkte Flaschen", ["text"] = "Wird beim Aufheben gebunden\n\"Dreiwandige Fläschchen sind entscheidend für die Aufbewahrung der tödlichen Flüssigkeiten, die das Haus der Seuchen für seine Experimente verwendet.\"\nVerkaufspreis:" }
entries[181728] = { ["name"] = "Makellose Fleischnähernadeln", ["text"] = "Wird beim Aufheben gebunden\n\"Diese aus den Knochen von Maldraxxus selbst geschnitzten Nadeln sind ein begehrtes Erzeugnis aus dem Haus der Konstrukte.\"\nVerkaufspreis:" }
entries[181729] = { ["name"] = "Prototyp einer Phylakteriumform", ["text"] = "Wird beim Aufheben gebunden\n\"Das Haus der Lichs arbeitet ständig an der Verbesserung seiner Phylakterien, damit diese widerstandsfähiger gegen Zerstörungsversuche werden.\"\nVerkaufspreis:" }
entries[181730] = { ["name"] = "Geschmiedeter Oxxeinschleifstein", ["text"] = "Wird beim Aufheben gebunden\n\"Disziplinierte Soldaten in Maldraxxus halten ihre Waffen scharf und sind bereit, die Schattenlande um jeden Preis zu verteidigen.\"\nVerkaufspreis:" }
entries[181731] = { ["name"] = "Lackierter Larionreißzahn", ["text"] = "Wird beim Aufheben gebunden\n\"Einem schlafenden Larion einen Reißzahn zu entfernen, war eine der vielen Prüfungen, die für die Aufnahme in das Haus der Augen bestanden werden mussten.\"\nVerkaufspreis:" }
