entries[181761] = { ["name"] = "Gutschein des Großmeisters", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Dieser Gutschein bestätigt widerwillig, dass der Großmeister eine Wette verloren hat und dem Inhaber des Papiers die vereinbarte Summe aushändigen wird. Au'narim im Theater der Schmerzen wird die Auszahlung genehmigen und Euch das Geld geben.\"" }
