entries[181765] = { ["name"] = "Marcel Mullbys Marke", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Großmeister Vole hatte nie die Absicht, ein Geschenk mitzubringen, hat sich jedoch amüsiert und diese Marke in die Gabenkiste geworfen. Wenn Ihr sie Marcel zurückbringt, wird er Euch sicher eine beträchtliche Summe bieten, um seine Marke zurückzubekommen.\"" }
