entries[181815] = { ["name"] = "Gepanzerter Knochenhuftauralus", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Der Tauralus ist das bevorzugte Reittier des Hauses der Auserwählten, denn er wird im Kampf noch wütender und bösartiger.\"\nBeute von:\nSabriel die Knochenspalterin\nPakt:\nNekrolords\nZone:\nMaldraxxus" }
entries[181816] = { ["name"] = "Siegel der Anpassung des sündigen Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Medaillons des Gladiators (1)\nSchmuck\n+28 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Entfernt alle Effekte mit einer Dauer von 5 Sek. oder mehr, die Kontrollverlust bewirken. Dieser Effekt kann nur einmal alle 1 Min. auftreten.\n\nAuszeichnung des Gladiators (0/2)\nEmblem des Gladiators\nMedaillon des Gladiators\n(2) Set : Erhöht in Arenen, auf Schlachtfeldern und im Kriegsmodus Eure Hauptwert um 12% und Eure Ausdauer um 20%.\nVerkaufspreis:" }
entries[181817] = { ["name"] = "Fledderflügel des Todesbringers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten" }
entries[181818] = { ["name"] = "Durchgekaute Zügel des kahlen Fledderflügels", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Fledderflügel sind notwendig für den Kreislauf des Lebens in den Schattenlanden. In der rauen Umgebung von Maldraxxus sind sie sowohl Räuber als auch Beute.\"\nZone:\nMaldraxxus" }
entries[181819] = { ["name"] = "Markzahns Zügel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Der unersättliche Appetit von Markzahn, Nachkomme von Knochenzahn, wurde von Amarth dem Ernter geschätzt, auch wenn er die Experimente des sadistischen Kommandanten störte.\"\nBeute:\nNalthor der Eisbinder\nZone:\nDie Nekrotische Schneise (Mythisch)\n\nBeute:\nSchatz des Herausforderers\nZone:\nDie Nekrotische Schneise" }
entries[181820] = { ["name"] = "Gepanzerter auserwählter Tauralus", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Der Tauralus hat zwei Schweife, die unentbehrlich sind, um lästiges herumschwirrendes Ungeziefer wie die Blutlaus wegzupeitschen.\"\nErfolg:\nAbhakliste für Tote\nKategorie:\nPaktsankten" }
entries[181821] = { ["name"] = "Gepanzerter Seuchenfäulnistauralus", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Ruhmstufe 39\n\n\"Ein voll gepanzerter Tauralus kann unglaubliche Mengen an Schaden einstecken, bevor er zu Boden geht. Das macht ihn in jeder Schlacht zu einem wertvollen Verbündeten.\"\nPakt:\nNekrolords\nVerkäufer:\nSu Zettai\nZone:\nMaldraxxus\nKosten:\n3000" }
entries[181822] = { ["name"] = "Gepanzerter kriegsgezüchteter Tauralus", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Den Tauralussen, die den Armeen von Maldraxxus dienen, wurde jegliches Mitgefühl durch Züchtung ausgetrieben. Sie sind nur mit Rüstungen geschmückt, um zu demonstrieren, dass kein Schwert und kein Zauber sie daran hindern kann, ihre Reiter zum Sieg zu tragen.\"\nPakt:\nNekrolords\nZone:\nMaldraxxus" }
