entries[182074] = { ["name"] = "Auserwählter Tauralus", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Selbst ein ungepanzerter Tauralus ist im Kampf ein wertvoller Verbündeter, denn seine gewaltigen Hörner können sogar eine Plattenrüstung durchbohren.\"\nErfolg:\nMonströse Montage\nKategorie:\nPaktsankten" }
entries[182075] = { ["name"] = "Knochenhuftauralus", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Es gibt viele gute Gründe, warum man nicht hinter einem Tauralus stehen sollte. Ihre Hufe und peitschenartigen Schweife gehören dabei noch zu den kleineren Übeln.\"\nBeute von:\nTahonta\nPakt:\nNekrolords\nZone:\nMaldraxxus" }
entries[182076] = { ["name"] = "Seuchenfäulnistauralus", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Ruhmstufe 23\n\n\"Die Tauralus gelten gemeinhin als mutige Wesen, doch die Gelehrten von Maldraxxus fragen sich schon länger, ob ihre Furchtlosigkeit nur ein Nebenprodukt ihrer winzigen Gehirne sein könnte.\"\nPakt:\nNekrolords\nZone:\nMaldraxxus" }
entries[182077] = { ["name"] = "Kriegsgezüchteter Tauralus", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Die Soldaten von Maldraxxus beschützen die Schattenlande und sind auf fähige Reittiere angewiesen, die selbst in scheinbar aussichtslosen Situationen die Ruhe bewahren.\"\nPakt:\nNekrolords\nZone:\nMaldraxxus" }
entries[182078] = { ["name"] = "Knochenvernähter Fleischroc", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Nur erfahrene Fleischnäher, die ihre meisterhafte Beherrschung der Magien von Maldraxxus unter Beweis gestellt haben, sind mächtig genug, einen Todesroc dieser Größe zu erschaffen.\"\nBeruf:\nMonstrositätenflickerei\nZone:\nMaldraxxus" }
entries[182079] = { ["name"] = "Schleimbedeckte Zügel des bulligen Todesrocs", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man einen bulligen Todesroc beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Todesrocs sind Monstrositäten, zusammengeflickt aus Eingeweiden, Knochen und Organen, die nicht zum Bau von Soldaten im Haus der Konstrukte gebraucht wurden.\"\nBeute von:\nVioletter Fehler\nZone:\nMaldraxxus" }
entries[182080] = { ["name"] = "Räuberischer Seuchenroc", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Giegers unstillbarer Hunger ist im Haus der Konstrukte legendär, und kein Tier ist zu groß oder zu knochig, um in seinen riesigen Magen zu passen.\"\nBeute von:\nGieger\nPakt:\nNekrolords\nZone:\nMaldraxxus" }
entries[182081] = { ["name"] = "Zügel der riesigen Massakerklaue", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man eine riesige Massakerklaue beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Nur die standhaftesten Stallmeister von Maldraxxus sind in der Lage, die riesigen Massakerklauen zu unterwerfen, und so allen Champions der Unvergänglichen Armee einen furchterregenden Verbündeten in den Schattenlanden zur Seite zu stellen.\"\nBeute von:\nVorräte der Unvergänglichen Armee\nZone:\nMaldraxxus" }
entries[182082] = { ["name"] = "Blutrünstiger Bluthauer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Die Unvergängliche Armee\n- Ehrfürchtig\n\n\"Nur Bluthauer, die den Wettstreit der Eroberung überleben, gelten als würdig, als Reittier der Unvergängliche Armee zu dienen.\"\nVerkäufer:\nNalcorn Talsen\nZone:\nMaldraxxus\nFraktion:\nDie Unvergängliche Armee - Ehrfürchtig\nKosten:" }
entries[182083] = { ["name"] = "Schädeleber des Knochenspalters", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Sabriel war für die ruchlose Effizienz bekannt, mit der sie ihre Gegner zerlegte, um deren Knochen an ihren loyalen Schädeleber zu verfüttern.\"\nVerkäufer:\nSammler Ta'steld\nZone:\nOribos\nKosten:\n5.000" }
entries[182084] = { ["name"] = "Blutstachel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Nerissa ist mit Blutstachel über unzählige Leichen gegangen, um zur Kommandantin der lichverschworenen Streitkräfte im Haus der Rituale aufzusteigen.\"\nBeute:\nNerissa Herzlos\nZone:\nMaldraxxus" }
entries[182085] = { ["name"] = "Pustelrückenbluthauer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Das Haus der Auserwählten trainiert seine Reittiere unter verschiedensten widrigen Umständen, damit sie nie wanken, ganz gleich, in welcher Schlacht sie benötigt werden.\"\nBeute:\nKriegshetzer Mal'korak\nZone:\nMaldraxxus" }
